class PriceService {
    private final TaxClient client;

    PriceService(TaxClient client) {
        this.client = client;
    }

    int withTax(int net) {
        int rate;
        try {
            rate = client.ratePercent();
        } catch (IllegalStateException error) {
            rate = 0;
        }
        return net + net * rate / 100;
    }
}

